<?php require dirname(__DIR__,2).'/layouts/admin_start.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$filter=$_GET['status']??'active';?>
<section class="equipment-grid"><article class="content-card"><h2 id="equipment-title">Cadastrar equipamento</h2><form class="admin-form" id="equipment-form" method="post" action="/admin/equipment/save"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="id"><div class="form-grid"><label><span>Código *</span><input name="code" required></label><label><span>Nome *</span><input name="name" required></label><label><span>Fabricante *</span><input name="manufacturer" required></label><label><span>Modelo *</span><input name="model" required></label><label><span>Nº de série</span><input name="serial_number"></label><label><span>Unidade</span><select name="unit_id"><option value="">Todas / não vinculada</option><?php foreach($units as$u):?><option value="<?=$u['id']?>"><?=$h($u['name'])?></option><?php endforeach?></select></label><label><span>Vigente desde *</span><input type="date" name="effective_from" required></label><label><span>Vigente até</span><input type="date" name="effective_to"></label><label class="check"><input type="checkbox" name="active" value="1" checked> Ativo</label></div><div class="form-actions"><button class="button">Salvar equipamento</button> <button class="button button-secondary" type="reset" data-cancel-edit hidden>Cancelar edição</button></div></form></article>
<article class="content-card"><h2 id="assignment-title">Associar a teste</h2><form class="admin-form" id="assignment-form" method="post" action="/admin/equipment/assign"><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="id"><label><span>Teste *</span><select name="test_id" required><option value="">Selecione</option><?php foreach($tests as$t):?><option value="<?=$t['id']?>"><?=$h(($t['code']?:'—').' - '.$t['name'])?></option><?php endforeach?></select></label><label><span>Hemocomponente opcional</span><select name="blood_component_id"><option value="">Todos</option><?php foreach($components as$c):?><option value="<?=$c['id']?>"><?=$h($c['code'].' - '.$c['name'])?></option><?php endforeach?></select></label><label><span>Equipamento *</span><select name="equipment_id" required><option value="">Selecione</option><?php foreach($equipment as$e):if($e['active']):?><option value="<?=$e['id']?>"><?=$h($e['code'].' - '.$e['name'].' '.$e['model'])?></option><?php endif;endforeach?></select></label><label><span>Vigente desde *</span><input type="date" name="effective_from" required></label><label><span>Vigente até</span><input type="date" name="effective_to"></label><label class="check"><input type="checkbox" name="active" value="1" checked> Ativo</label><button class="button">Salvar vínculo</button> <button class="button button-secondary" type="reset" data-cancel-assignment hidden>Cancelar edição</button></form></article></section>
<section class="content-card"><div class="section-heading"><div><h2>Equipamentos</h2><p>Inativos permanecem disponíveis para auditoria, mas não para novos resultados.</p></div><form method="get"><select name="status" onchange="this.form.submit()"><option value="active" <?=$filter==='active'?'selected':''?>>Ativos</option><option value="inactive" <?=$filter==='inactive'?'selected':''?>>Inativos</option><option value="all" <?=$filter==='all'?'selected':''?>>Todos</option></select></form></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Nome</th><th>Fabricante / Modelo</th><th>Unidade</th><th>Vigência</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($equipment as$e):if(($filter==='active'&&!$e['active'])||($filter==='inactive'&&$e['active']))continue;$json=$h(json_encode($e,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT));?><tr><td><?=$h($e['code'])?></td><td><?=$h($e['name'])?></td><td><?=$h($e['manufacturer'].' / '.$e['model'])?></td><td><?=$h($e['unit_name']?:'—')?></td><td><?=date('d/m/Y',strtotime($e['effective_from']))?><?=$e['effective_to']?' a '.date('d/m/Y',strtotime($e['effective_to'])):''?></td><td><span class="status status-<?=$e['active']?'active':'inactive'?>"><?=$e['active']?'Ativo':'Inativo'?></span></td><td><div class="table-actions"><button class="table-action" type="button" data-edit-equipment='<?=$json?>'>Editar</button><button class="table-action <?=$e['active']?'table-action-warning':'table-action-positive'?>" type="button" data-action="/admin/equipment/toggle" data-id="<?=$e['id']?>" data-active="<?=$e['active']?0:1?>" data-message="<?=$e['active']?'Inativar este equipamento e seus vínculos ativos?':'Reativar este equipamento?'?>"><?=$e['active']?'Inativar':'Ativar'?></button><button class="table-action table-action-danger" type="button" data-action="/admin/equipment/delete" data-id="<?=$e['id']?>" data-message="Excluir definitivamente este equipamento? A exclusão só será concluída se não houver histórico.">Excluir</button></div></td></tr><?php endforeach?></tbody></table></div></section>
<section class="content-card"><h2>Vínculos com testes</h2><div class="table-wrap"><table><thead><tr><th>Teste</th><th>Hemocomponente</th><th>Equipamento</th><th>Vigência</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($assignments as$a):$json=$h(json_encode($a,JSON_UNESCAPED_UNICODE|JSON_HEX_APOS|JSON_HEX_QUOT));?><tr><td><?=$h($a['test_code'].' - '.$a['test_name'])?></td><td><?=$h($a['component_code']?:'Todos')?></td><td><?=$h($a['equipment_name'])?></td><td><?=date('d/m/Y',strtotime($a['effective_from']))?><?=$a['effective_to']?' a '.date('d/m/Y',strtotime($a['effective_to'])):''?></td><td><span class="status status-<?=$a['active']?'active':'inactive'?>"><?=$a['active']?'Ativo':'Inativo'?></span></td><td><div class="table-actions"><button class="table-action" type="button" data-edit-assignment='<?=$json?>'>Editar</button><button class="table-action" type="button" data-action="/admin/equipment/assignment/toggle" data-id="<?=$a['id']?>" data-active="<?=$a['active']?0:1?>" data-message="<?=$a['active']?'Inativar este vínculo?':'Reativar este vínculo?'?>"><?=$a['active']?'Inativar':'Ativar'?></button><button class="table-action table-action-danger" type="button" data-action="/admin/equipment/assignment/delete" data-id="<?=$a['id']?>" data-message="Excluir definitivamente este vínculo? Usos históricos bloquearão a operação.">Excluir</button></div></td></tr><?php endforeach?></tbody></table></div></section>
<dialog class="shipment-cancel-dialog" id="confirm-dialog"><form method="post"><div class="dialog-heading"><h3>Confirmar ação</h3><button class="dialog-close" type="button" data-close>×</button></div><input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="id"><input type="hidden" name="active"><p data-message></p><div class="dialog-actions"><button class="button button-secondary" type="button" data-close>Cancelar</button><button class="button button-danger" type="submit">Confirmar</button></div></form></dialog>
<script>(()=>{const fill=(form,data)=>Object.entries(data).forEach(([k,v])=>{const el=form.elements[k];if(!el)return;if(el.type==='checkbox')el.checked=!!Number(v);else el.value=v??''});const ef=document.querySelector('#equipment-form'),af=document.querySelector('#assignment-form');document.querySelectorAll('[data-edit-equipment]').forEach(b=>b.onclick=()=>{fill(ef,JSON.parse(b.dataset.editEquipment));document.querySelector('#equipment-title').textContent='Editar equipamento';ef.querySelector('[data-cancel-edit]').hidden=false;ef.scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-edit-assignment]').forEach(b=>b.onclick=()=>{const d=JSON.parse(b.dataset.editAssignment);d.blood_component_id=d.blood_component_id??'';fill(af,d);document.querySelector('#assignment-title').textContent='Editar vínculo';af.querySelector('[data-cancel-assignment]').hidden=false;af.scrollIntoView({behavior:'smooth'})});const dialog=document.querySelector('#confirm-dialog'),form=dialog.querySelector('form');document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{form.action=b.dataset.action;form.elements.id.value=b.dataset.id;form.elements.active.value=b.dataset.active??'';dialog.querySelector('[data-message]').textContent=b.dataset.message;dialog.showModal()});dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close())})();</script>
<?php require dirname(__DIR__,2).'/layouts/admin_end.php';?>
